(function(){
 window.createMaisonStorefront=function(){
 const config=window.MAISON,$=id=>document.getElementById(id),products=config.products.filter(p=>p.status==='published'),shows=config.showcases;
 const basket=window.ToucheDorCart,indices=shows.map(()=>0);let active=-1,filter='all';
 try{const saved=JSON.parse(sessionStorage.getItem('touche-dor-visit')||'null');if(saved&&Array.isArray(saved.indices))saved.indices.forEach((v,i)=>{if(i<indices.length&&Number.isInteger(v)&&v>=0)indices[i]=v;});}catch{}
 const origins=new WeakMap(),money=v=>v.toLocaleString('fr-FR',{style:'currency',currency:'EUR'}),safe=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const image=p=>p.gallery?.[0];const candidates=i=>shows[i].productIds.map(id=>products.find(p=>p.id===id)).filter(Boolean);
 function photo(p){const img=image(p);return img?'<img src="'+safe(img.thumbnail)+'" width="'+img.width+'" height="'+img.height+'" alt="'+safe(img.alt)+'" loading="lazy">':'<span class="photo-missing">Photographie bientôt disponible</span>';}
 function toast(message){$('toast').textContent=message;$('toast').classList.add('o');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('o'),2600);}
 function persist(){const cart=basket.read(products);$('cartB').textContent='Panier ('+Object.values(cart).reduce((a,b)=>a+b,0)+')';}
 function add(id){basket.change(products,id,1);persist();toast('Ajouté au panier');if($('cart-dialog').open)drawCart();}
 function remember(){try{sessionStorage.setItem('touche-dor-visit',JSON.stringify({progress:scrollY/innerHeight,indices}));}catch{}}
 function restoreVisit(){try{if(!new URLSearchParams(parent.location.search).has('reprendre')&&!new URLSearchParams(location.search).has('reprendre'))return;const saved=JSON.parse(sessionStorage.getItem('touche-dor-visit')||'null');if(saved&&Number.isFinite(saved.progress))scrollTo({top:Math.max(0,saved.progress)*innerHeight,behavior:'instant'});}catch{}}
 function visit(id){const p=products.find(p=>p.id===id);if(p){remember();window.top.location.href='/produits/'+p.slug;}}
 function open(dialog){origins.set(dialog,document.activeElement);dialog.showModal();document.documentElement.style.overflowY='hidden';}
 document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.documentElement.style.overflowY='';const origin=origins.get(dialog);if(origin?.isConnected)origin.focus({preventScroll:true});});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
 function tile(p){return '<article class="product-tile"><a data-product href="/produits/'+p.slug+'" target="_top" class="product-visual">'+photo(p)+'</a><h3>'+safe(p.name)+'</h3><p class="muted">'+safe(p.desc)+'</p><p>'+money(p.price)+'</p><div class="actions"><a class="classic-button" data-product href="/produits/'+p.slug+'" target="_top">Voir le produit</a><button class="gold" data-add="'+p.id+'">Ajouter au panier</button></div></article>';}
 function drawCatalogue(){const choices=[['all','Toutes les pièces'],...shows.map(s=>[s.id,s.category])];$('filters').innerHTML=choices.map(([id,label])=>'<button data-filter="'+id+'" aria-pressed="'+(filter===id)+'">'+safe(label)+'</button>').join('');const list=filter==='all'?products:candidates(shows.findIndex(s=>s.id===filter));$('list').innerHTML=list.length?list.map(tile).join(''):'<p class="empty-state">Une nouvelle sélection se prépare dans cet univers.</p>';$('catalogue-title').textContent=filter==='all'?'Toutes les pièces':shows.find(s=>s.id===filter).name;}
 function catalogue(category='all'){filter=category;drawCatalogue();open($('catalogue'));}
 function drawCard(){if(active<0)return;const show=shows[active],list=candidates(active);indices[active]%=Math.max(1,list.length);const p=list[indices[active]];$('ch').textContent='Vitrine '+String(active+1).padStart(2,'0')+' / 06 · '+show.category;$('nm').textContent=p?p.name:show.name;$('mt').textContent=p?p.desc:'Une nouvelle sélection se prépare.';$('pr').textContent=p?money(p.price):'';$('card-count').textContent=list.length?(indices[active]+1)+' / '+list.length:'À découvrir prochainement';$('card-prev').disabled=$('card-next').disabled=list.length<2;$('view-product').hidden=$('add').hidden=!p;$('card-pending').textContent=p?'Livraison gratuite':'';const img=p&&image(p);if(img){const element=$('card-photo');element.style.transition='none';element.style.opacity='0';element.onload=()=>{element.style.transition=matchMedia('(prefers-reduced-motion: reduce)').matches?'none':'opacity .16s ease';element.style.opacity='1';};element.onerror=()=>{element.style.opacity='0';};element.src=img.thumbnail;element.alt=img.alt;element.hidden=false;if(element.complete&&element.naturalWidth>0)element.style.opacity='1';}else{$('card-photo').hidden=true;$('card-photo').removeAttribute('src');}}
 function drawCart(){const cart=basket.read(products),lines=products.filter(p=>cart[p.id]);$('cart-list').innerHTML=lines.length?lines.map(p=>'<div class="cart-line"><div class="cart-thumb">'+photo(p)+'</div><div>'+safe(p.name)+'<p class="muted">'+money(p.price)+'</p><button data-remove="'+p.id+'">Supprimer</button></div><div class="quantity"><button data-qty="'+p.id+'" data-delta="-1" aria-label="Retirer un '+safe(p.name)+'">−</button><span>'+cart[p.id]+'</span><button data-qty="'+p.id+'" data-delta="1" aria-label="Ajouter un '+safe(p.name)+'">+</button></div></div>').join(''):'<p class="empty-state">Votre panier est vide.</p>';$('tot').textContent=money(lines.reduce((n,p)=>n+p.price*cart[p.id],0));$('out').disabled=true;$('out').textContent='Commande en ligne prochainement';}
 $('allB').onclick=()=>catalogue();$('cartB').onclick=()=>{persist();drawCart();open($('cart-dialog'));};$('add').onclick=()=>{const p=candidates(active)[indices[active]];if(p)add(p.id);};$('view-product').onclick=()=>{const p=candidates(active)[indices[active]];if(p)visit(p.id);};[-1,1].forEach(dir=>{$(dir<0?'card-prev':'card-next').onclick=()=>{const list=candidates(active);if(list.length<2)return;indices[active]=(indices[active]+dir+list.length)%list.length;drawCard();};});
 document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-product'))remember();if(el.dataset.add)add(el.dataset.add);if(el.dataset.filter){filter=el.dataset.filter;drawCatalogue();}if(el.dataset.category){event.preventDefault();catalogue(el.dataset.category);}if(el.dataset.qty){basket.change(products,el.dataset.qty,Number(el.dataset.delta));persist();drawCart();}if(el.dataset.remove){basket.change(products,el.dataset.remove,-99);persist();drawCart();}if(el.dataset.catalogue!==undefined){event.preventDefault();catalogue();}if(el.dataset.tour!==undefined){event.preventDefault();scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
 $('categories').innerHTML=shows.map((s,i)=>'<button class="category-tile" data-category="'+s.id+'"><small>Collection / 0'+(i+1)+'</small><div><h3>'+safe(s.name)+'</h3><span>'+(s.productIds.length?'Découvrir la sélection':'Prochainement')+'</span></div><span class="arrow" aria-hidden="true">↗</span></button>').join('');$('selection-grid').innerHTML=products.map(tile).join('');$('footer-categories').innerHTML=shows.map(s=>'<a href="#collections" data-category="'+s.id+'">'+safe(s.category)+'</a>').join('');const legal=[['contact','Contact'],['legal','Mentions légales'],['terms','Conditions générales de vente'],['privacy','Confidentialité'],['shipping','Livraison'],['returns','Retours']];$('footer-links').innerHTML=legal.filter(([key])=>config.brand[key]).map(([key,label])=>'<a href="'+safe(config.brand[key])+'">'+label+'</a>').join('')+'<span>Livraison gratuite</span>';$('socials').innerHTML=config.brand.socials.map(s=>'<a href="'+safe(s.url)+'" rel="noopener noreferrer">'+safe(s.label)+'</a>').join('');persist();
 return {setActive(index,visible){if(index!==active){active=index;if(index>=0&&index<6)drawCard();}const card=$('card');card.style.opacity=visible?'1':'0';card.style.pointerEvents=visible?'auto':'none';card.inert=!visible;},catalogue,toast,restoreVisit};
 };
})();
